package com.chatsystem.user.controller.group;import com.chatsystem.shared.service.GroupService;import com.chatsystem.user.navigation.*;import javafx.fxml.FXML;import javafx.scene.control.*;
public final class CreateGroupDialogController{private final GroupService groups;private final UserNavigator nav;@FXML private TextField groupNameField;@FXML private TextArea descriptionField;@FXML private Label feedbackLabel;public CreateGroupDialogController(GroupService g,UserNavigator n){groups=g;nav=n;}@FXML private void submit(){var r=groups.createGroup(groupNameField.getText(),descriptionField.getText());if(r.isSuccess()){groupNameField.getScene().getWindow().hide();nav.navigate(ViewRequest.conversation(UserRoute.GROUP_DETAILS,r.value().orElseThrow().getId()));}else feedbackLabel.setText(r.errors().get(0).message());}@FXML private void cancel(){groupNameField.getScene().getWindow().hide();}}
